/**
 * @file Track.h
 * @brief Biķernieku trase (Rīga) as a driving line: speed envelope, heading
 *        and, on the larger targets, the outline for maps.
 *
 * Distance `s` is metres from the start/finish line along the driven line and
 * wraps at length(). Data is generated by scripts/gen_track.py from
 * OpenStreetMap (© OpenStreetMap contributors, ODbL-1.0).
 */
#pragma once

#include <stdint.h>

namespace track {

const char* name();
float length();
/// Fastest the driver should be at `s`: corner grip limit with a braking
/// envelope for what follows, m/s.
float envelope(float s);
/// Driving direction at `s`, radians clockwise from north.
float heading(float s);
/// Signed curvature at `s`, 1/m (positive = turning right).
float curvature(float s);
/// Wrap any distance into [0, length).
float wrap(float s);

#ifdef TRACK_OUTLINE
/// Position at `s`, metres east/north of the start line.
void position(float s, float& x, float& y);
uint16_t outlinePoints();
void outlinePoint(uint16_t i, int16_t& x, int16_t& y);
double originLat();
double originLon();
#endif

}  // namespace track
